// ============================================================
// Merge: X509Cert
// ============================================================
// MergeX509Cert fills zero-valued fields in dst from src.
func MergeX509Cert(dst, src *X509Cert) {
	if dst.Id == "" {
		dst.Id = src.Id
	}
	if dst.Base64 == "" {
		dst.Base64 = src.Base64
	}
}

// ============================================================
// Merge: X509CertRequest
// ============================================================
// MergeX509CertRequest fills zero-valued fields in dst from src.
func MergeX509CertRequest(dst, src *X509CertRequest) {
	if dst.Key == nil {
		dst.Key = src.Key
	}
	if dst.Exp == 0 {
		dst.Exp = src.Exp
	}
	if dst.Metadata == nil {
		dst.Metadata = src.Metadata
	}
	if dst.KeyUsage == 0 {
		dst.KeyUsage = src.KeyUsage
	}
	if len(dst.ExtKeyUsage) == 0 {
		dst.ExtKeyUsage = src.ExtKeyUsage
	}
	if dst.Issuer == "" {
		dst.Issuer = src.Issuer
	}
	if !dst.IsCa {
		dst.IsCa = src.IsCa
	}
	if dst.PathLenConstraint == 0 {
		dst.PathLenConstraint = src.PathLenConstraint
	}
	if len(dst.DnsNames) == 0 {
		dst.DnsNames = src.DnsNames
	}
	if len(dst.UriSans) == 0 {
		dst.UriSans = src.UriSans
	}
}

// ============================================================
// Merge: X509CertChain
// ============================================================
// MergeX509CertChain fills zero-valued fields in dst from src.
func MergeX509CertChain(dst, src *X509CertChain) {
	if len(dst.Chain) == 0 {
		dst.Chain = src.Chain
	}
	if dst.Key == nil {
		dst.Key = src.Key
	}
	if dst.Id == "" {
		dst.Id = src.Id
	}
}
